const topics = [
  {
    topic: '海洋散骨',
    description: '大切な方の遺骨を海に還す「海洋散骨」のメリット・費用・手続き・注意点'
  },
  {
    topic: 'お墓じまい',
    description: 'お墓を閉じて改葬・永代供養に移行する「墓じまい」の流れと費用'
  },
  {
    topic: '粉骨サービス',
    description: '遺骨を粉末状にする「粉骨」とその後の散骨・手元供養への活用'
  },
  {
    topic: '手元供養',
    description: '遺骨の一部を自宅で大切に保管する「手元供養」の種類と選び方'
  },
  {
    topic: '樹木葬',
    description: '木の根元に埋葬する自然葬「樹木葬」の特徴・費用・選ぶ際のポイント'
  },
  {
    topic: '永代供養',
    description: '寺院・霊園が長期間供養してくれる「永代供養」の種類と費用感'
  },
  {
    topic: '散骨の法律と注意点',
    description: '日本における散骨（海洋・山・宇宙）の法的位置づけとマナー'
  },
  {
    topic: '終活の始め方',
    description: '50〜60代から始める終活の具体的なステップと遺骨の準備'
  }
];

const selected = topics[Math.floor(Math.random() * topics.length)];
return [{ json: selected }];

const response = $input.item.json;
const rawText = response.content[0].text.trim();

let parsed;
try {
  // ```json ... ``` で囲まれている場合も対応
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('JSONが見つかりません');
  parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  throw new Error('Claude レスポンスのパース失敗: ' + rawText.substring(0, 300));
}

if (!parsed.title || !parsed.body) {
  throw new Error('title または body が見つかりません');
}

// UUID v4 生成
const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

return [{
  json: {
    key: uuid,
    title: parsed.title,
    body: parsed.body
  }
}];

const result = $input.item.json;

if (result.error || result.code) {
  throw new Error('Note.com 投稿失敗: ' + JSON.stringify(result));
}

console.log('投稿成功:', JSON.stringify(result, null, 2));
return [{ json: { success: true, note_url: result.data?.note_url || result.url || '投稿完了', title: result.data?.title } }];
